import React from 'react';
import { BrowserRouter, Routes, Route, NavLink } from 'react-router-dom';
import Wizard from './pages/Wizard';
import EventLog from './pages/EventLog';
import './App.css';

function App() {
  return (
    <BrowserRouter>
      <div className="app-shell">
        {/* ── Sidebar ── */}
        <aside className="sidebar">
          <div className="sidebar-logo">
            <span className="logo-icon">◈</span>
            <span className="logo-text">CT<br/>Integrator</span>
          </div>
          <nav className="sidebar-nav">
            <NavLink to="/"         end className={({isActive}) => isActive ? 'nav-item active' : 'nav-item'}>
              <span className="nav-icon">⚡</span> Setup Wizard
            </NavLink>
            <NavLink to="/eventlog"     className={({isActive}) => isActive ? 'nav-item active' : 'nav-item'}>
              <span className="nav-icon">📋</span> Event Log
            </NavLink>
          </nav>
          <div className="sidebar-footer">
            <span className="powered-by">Powered by CleverTap API</span>
          </div>
        </aside>

        {/* ── Main content ── */}
        <main className="main-content">
          <Routes>
            <Route path="/"         element={<Wizard />} />
            <Route path="/eventlog" element={<EventLog />} />
          </Routes>
        </main>
      </div>
    </BrowserRouter>
  );
}

export default App;
